import os
import re
from collections import defaultdict

REPO = "/bench/repo"
STORE_PREFIX = os.path.join(REPO, "store")

def is_store_layer(path):
    rel = os.path.relpath(path, REPO)
    return rel == "store" or rel.startswith("store" + os.sep)

def package_dir(filepath):
    return os.path.dirname(filepath)

def get_go_files():
    files = []
    for root, dirs, filenames in os.walk(REPO):
        if "/.git/" in root.replace("\\", "/"):
            continue
        for fn in filenames:
            if fn.endswith(".go"):
                files.append(os.path.join(root, fn))
    return files

# Core persistent entity types from driver.go model comments and struct definitions
ENTITY_TYPES = [
    "Attachment", "IdentityProvider", "Inbox", "InstanceSetting",
    "Memo", "MemoRelation", "MemoShare", "Reaction",
    "User", "UserIdentity", "UserSetting",
]
# Supporting persisted enum/value types
ENUM_TYPES = ["RowStatus", "Role", "Visibility", "MemoRelationType", "InboxStatus"]

all_files = get_go_files()
external_files = [f for f in all_files if not is_store_layer(f)]

# Map package dir -> set of entity types referenced
entity_pkg_refs = {e: set() for e in ENTITY_TYPES}
enum_pkg_refs = {e: set() for e in ENUM_TYPES}

# Patterns for qualified references
def patterns_for(name):
    return [
        re.compile(r'\bstore\.' + re.escape(name) + r'\b'),
        re.compile(r'\bstore\.' + re.escape(name) + r'\{'),
    ]

entity_patterns = {e: patterns_for(e) for e in ENTITY_TYPES}
enum_patterns = {e: patterns_for(e) for e in ENUM_TYPES}

# Also detect unqualified use when file imports store package
store_import_re = re.compile(r'"github\.com/usememos/memos/store"')
unqualified_re = {e: re.compile(r'(?<![A-Za-z0-9_])' + re.escape(e) + r'(?![A-Za-z0-9_])') for e in ENTITY_TYPES + ENUM_TYPES}

for fpath in external_files:
    try:
        content = open(fpath, encoding='utf-8').errors='replace').read()
    except Exception:
        continue
    pkg = package_dir(fpath)
    imports_store = bool(store_import_re.search(content))

    for entity in ENTITY_TYPES:
        matched = any(p.search(content) for p in entity_patterns[entity])
        if not matched and imports_store:
            # unqualified reference - exclude Find/Update/Delete prefixed false positives for related types
            if unqualified_re[entity].search(content):
                matched = True
        if matched:
            entity_pkg_refs[entity].add(pkg)

    for enum in ENUM_TYPES:
        matched = any(p.search(content) for p in enum_patterns[enum])
        if not matched and imports_store and unqualified_re[enum].search(content):
            matched = True
        if matched:
            enum_pkg_refs[enum].add(pkg)

print("=== PERSISTENT ENTITY TYPES (external package counts) ===")
for e in sorted(ENTITY_TYPES, key=lambda x: -len(entity_pkg_refs[x])):
    pkgs = sorted(entity_pkg_refs[e])
    print(f"{e:20s} {len(pkgs):3d}  {pkgs}")

print("\n=== ENUM/VALUE TYPES (external package counts) ===")
for e in sorted(ENUM_TYPES, key=lambda x: -len(enum_pkg_refs[x])):
    pkgs = sorted(enum_pkg_refs[e])
    print(f"{e:20s} {len(pkgs):3d}  {pkgs}")
