use strict; use warnings;
my $repo = "/bench/repo";
my @entities = qw(Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare Reaction User UserIdentity UserSetting);
my @enums = qw(RowStatus Role Visibility MemoRelationType InboxStatus);
my %refs; $refs{$_} = {} for @entities, @enums;

sub is_store {
  my ($f) = @_;
  return 1 if $f =~ m{^\Q$repo\E/store(/|$)};
  return 0;
}

opendir(my $dh, $repo) or die;
# walk all go files
use File::Find;
find(sub {
  return unless /\.go$/;
  return if is_store($File::Find::name);
  open my $fh, "<", $File::Find::name or return;
  local $/; my $c = <$fh>; close $fh;
  my $pkg = $File::Find::name; $pkg =~ s{/[^/]+$}{};
  my $imports_store = ($c =~ /"github\.com\/usememos\/memos\/store"/);
  for my $e (@entities, @enums) {
    my $hit = 0;
    $hit = 1 if $c =~ /\bstore\.$e\b/;
    if (!$hit && $imports_store) {
      $hit = 1 if $c =~ /(?<![A-Za-z0-9_])$e(?![A-Za-z0-9_])/;
    }
    $refs{$e}{$pkg} = 1 if $hit;
  }
}, $repo);

print "=== PERSISTENT ENTITY TYPES ===\n";
for my $e (sort { scalar(keys %{$refs{$b}}) <=> scalar(keys %{$refs{$a}}) } @entities) {
  my @pkgs = sort keys %{$refs{$e}};
  printf "%-20s %3d  %s\n", $e, scalar(@pkgs), join(", ", @pkgs);
}
print "\n=== ENUM TYPES ===\n";
for my $e (sort { scalar(keys %{$refs{$b}}) <=> scalar(keys %{$refs{$a}}) } @enums) {
  my @pkgs = sort keys %{$refs{$e}};
  printf "%-20s %3d  %s\n", $e, scalar(@pkgs), join(", ", @pkgs);
}
'

